def init_orm():
    DATA.mkdir(parents=True, exist_ok=True)
    # Register the optional global expedition models before creating tables.
    # Importing here avoids a module cycle while preserving the existing ORM.
    from . import expedition_orm  # noqa: F401
    Base.metadata.create_all(engine)
    columns = {column["name"] for column in inspect(engine).get_columns("orm_workspaces")}
    additions = {"execution_mode": "VARCHAR(16) DEFAULT 'demo' NOT NULL", "provider_name": "VARCHAR(64) DEFAULT 'fake' NOT NULL", "provider_model": "VARCHAR(128) DEFAULT '' NOT NULL"}
    with engine.begin() as connection:
        for name, definition in additions.items():
            if name not in columns:
                connection.execute(text(f"ALTER TABLE orm_workspaces ADD COLUMN {name} {definition}"))
    source_columns = {column["name"] for column in inspect(engine).get_columns("orm_sources")}
    source_additions = {"archive_preview_id": "VARCHAR(64) DEFAULT '' NOT NULL", "archive_relative_path": "TEXT DEFAULT '' NOT NULL", "parent_archive_name": "VARCHAR(240) DEFAULT '' NOT NULL", "language": "VARCHAR(32) DEFAULT '' NOT NULL"}
    with engine.begin() as connection:
        for name, definition in source_additions.items():
            if name not in source_columns:
                connection.execute(text(f"ALTER TABLE orm_sources ADD COLUMN {name} {definition}"))
    run_columns = {column["name"] for column in inspect(engine).get_columns("orm_learning_runs")}
    run_additions = {"last_idempotency_key": "VARCHAR(160) DEFAULT '' NOT NULL", "last_response": "JSON DEFAULT '{}' NOT NULL"}
    with engine.begin() as connection:
        for name, definition in run_additions.items():
            if name not in run_columns:
                connection.execute(text(f"ALTER TABLE orm_learning_runs ADD COLUMN {name} {definition}"))
    message_columns = {column["name"] for column in inspect(engine).get_columns("orm_learning_run_messages")}
    with engine.begin() as connection:
        if "idempotency_key" not in message_columns:
            connection.execute(text("ALTER TABLE orm_learning_run_messages ADD COLUMN idempotency_key VARCHAR(160) DEFAULT '' NOT NULL"))
    expedition_columns = {column["name"] for column in inspect(engine).get_columns("orm_expedition_profiles")}
    with engine.begin() as connection:
        if "gacha_state" not in expedition_columns:
            connection.execute(text("ALTER TABLE orm_expedition_profiles ADD COLUMN gacha_state JSON DEFAULT '{}' NOT NULL"))
